+    tey = (by - (prevY + r)) / ball.vy;
+    teyt = (by + bh - (prevY - r)) / ball.vy;
+  } else if (ball.vy < 0) {
+    tey = (by + bh - (prevY - r)) / ball.vy;
+    teyt = (by - (prevY + r)) / ball.vy;
+  } else if (prevY + r > by && prevY - r < by + bh) {
+    tey = -Infinity;
+    teyt = Infinity;
+  } else {
+    return null;
+  }
+
+  // The swept box crosses the brick iff the two overlap intervals intersect
+  // somewhere inside this step.
+  const tIn = Math.max(tex, tey);
+  const tOut = Math.min(text, teyt);
