edits.newText:
// --- Issue #1: the ball must bounce off bricks ------------------------------
//
// Each case mirrors one scenario from ISSUES.md #1: per-face bounce (the axis
// with the smaller penetration flips, the other component is untouched),
// corner hit (both components flip), push-out (the ball must leave the brick
// rectangle, otherwise it re-overlaps and re-flips forever), neighbours (the
// grid seam overlaps two bricks in the same pass — the bounce must apply
// exactly once) and tunnelling (a fast ball must be caught by a sweep between
// the previous and the current position).

const BRICK = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
const DT = 1 / 60;

test('brick: left side hit flips vx, keeps vy, pushes the ball out', () => {
  const state = createState(1);
  state.bricks = [{ ...BRICK }];
  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };

  step(state, DT);

  assert.ok(state.ball.vx < 0, `vx should flip to the left: ${state.ball.vx}`);
  assert.equal(state.ball.vy, 30, 'vy must stay exactly as it was');
  assert.ok(state.ball.x + BALL_R <= 100 + 1e-9, 'ball must be pushed out of the brick');
  assert.equal(state.bricks[0].alive, false, 'brick must be destroyed');
});

test('brick: right side hit flips vx, keeps vy', () => {
  const state = createState(1);
  state.bricks = [{ ...BRICK }];
  state.ball = { x: 176, y: 110, r: BALL_R, vx: -300, vy: 30 };

  step(state, DT);

  assert.ok(state.ball.vx > 0, `vx should flip to the right: ${state.ball.vx}`);
  assert.equal(state.ball.vy, 30, 'vy must stay exactly as it was');
  assert.ok(state.ball.x - BALL_R >= 172 - 1e-9, 'ball must be pushed out of the brick');
});

test('brick: top face hit flips vy, keeps vx', () => {
  const state = createState(1);
  state.bricks = [{ ...BRICK }];
  state.ball = { x: 136, y: 96, r: BALL_R, vx: 30, vy: 300 };

  step(state, DT);

  assert.ok(state.ball.vy < 0, `vy should flip upward: ${state.ball.vy}`);
  assert.equal(state.ball.vx, 30, 'vx must stay exactly as it was');
  assert.ok(state.ball.y + BALL_R <= 100 + 1e-9, 'ball must be pushed out of the brick');
});

test('brick: bottom face hit flips vy, keeps vx', () => {
  const state = createState(1);
  state.bricks = [{ ...BRICK }];
  state.ball = { x: 136, y: 124, r: BALL_R, vx: 30, vy: -300 };

  step(state, DT);

  assert.ok(state.ball.vy > 0, `vy should flip downward: ${state.ball.vy}`);
  assert.equal(state.ball.vx, 30, 'vx must stay exactly as it was');
  assert.ok(state.ball.y - BALL_R >= 120 - 1e-9, 'ball must be pushed out of the brick');
});

test('brick: corner hit flips both components', () => {
  const state = createState(1);
  state.bricks = [{ ...BRICK }];
  state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };

  step(state, DT);

  assert.ok(state.ball.vx < 0, `vx should flip: ${state.ball.vx}`);
  assert.ok(state.ball.vy < 0, `vy should flip: ${state.ball.vy}`);
});

test('brick: horizontal seam between two bricks bounces exactly once', () => {
  const state = createState(1);
  state.bricks = [
    { ...BRICK },
    { ...BRICK, x: 100 + BRICK_W + BRICK_GAP },
  ];
  // Centered on the seam, 1 px below the bricks' bottom faces: the vertical
  // axis wins for both bricks. A `vy = -vy` applied twice would cancel out.
  state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };

  step(state, DT);

  assert.ok(state.ball.vy > 0, `vy should flip exactly once: ${state.ball.vy}`);
  assert.ok(state.ball.vx > 0, `vx should be untouched: ${state.ball.vx}`);
});

test('brick: vertical seam between stacked bricks bounces exactly once', () => {
  const state = createState(1);
  state.bricks = [
    { ...BRICK },
    { ...BRICK, y: 100 + BRICK_H + BRICK_GAP, row: 1 },
  ];
  // Centered on the row seam, 1 px inside the bricks' left faces: the
  // horizontal axis wins for both bricks.
  state.ball = { x: 94, y: 124, r: BALL_R, vx: 60, vy: 6 };

  step(state, DT);

  assert.ok(state.ball.vx < 0, `vx should flip exactly once: ${state.ball.vx}`);
  assert.ok(state.ball.vy > 0, `vy should be untouched: ${state.ball.vy}`);
});

test('brick: fast ball does not tunnel through (swept collision)', () => {
  const state = createState(6);
  const brick = { ...BRICK };
  state.bricks = [brick];
  // Just below the brick; one stuttered frame at level 6 speed (710 px/s over
  // 50 ms = 35.5 px) lands fully above it. Only a sweep catches the crossing.
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };

  step(state, 0.05);

  assert.equal(brick.alive, false, 'brick must be broken');
  assert.ok(state.ball.vy > 0, `ball should bounce back down: ${state.ball.vy}`);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

