// True if the circle (cx, cy, r) overlaps the brick rectangle.
function overlapsBox(cx, cy, r, brick) {
  return (
    cx + r > brick.x &&
    cx - r < brick.x + brick.w &&
    cy + r > brick.y &&
    cy - r < brick.y + brick.h
  );
