// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The per-face bounce itself lives in step() (issue #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce (issue #1) ----------------------------------------------

// Tolerance used to decide that two entry times (or penetrations) are equal:
// that is the signature of a diagonal corner hit.
const PEN_EPS = 1e-9;

// Continuous (swept) collision test: does the ball, moving from (prevX, prevY)
// to its current position, cross `brick` during this step? If yes, returns the
// face that was hit — 'left' | 'right' | 'top' | 'bottom' | 'corner' — else
// null. Sweeping between the two positions closes the tunnelling hole: at
// level 6 a stuttered frame moves the ball 35.5 px, more than the 34 px it
// takes to cross a brick (see ISSUES.md #1).
function brickHitFace(ball, brick, prevX, prevY) {
  const { r } = ball;
  const { x: bx, y: by, w: bw, h: bh } = brick;

  // Entry / exit times along each axis, as a fraction of this step (0..1).
  // A negative entry time means the ball already overlapped that axis before
  // the move; -Infinity means it overlaps for the whole step.
  let tex, text;
  if (ball.vx > 0) {
    tex = (bx - (prevX + r)) / ball.vx;
    text = (bx + bw - (prevX - r)) / ball.vx;
  } else if (ball.vx < 0) {
    tex = (bx + bw - (prevX - r)) / ball.vx;
    text = (bx - (prevX + r)) / ball.vx;
  } else if (prevX + r > bx && prevX - r < bx + bw) {
    tex = -Infinity;
    text = Infinity;
  } else {
    return null;
  }

  let tey, teyt;
  if (ball.vy > 0) {
    tey = (by - (prevY + r)) / ball.vy;
    teyt = (by + bh - (prevY - r)) / ball.vy;
  } else if (ball.vy < 0) {
    tey = (by + bh - (prevY - r)) / ball.vy;
    teyt = (by - (prevY + r)) / ball.vy;
  } else if (prevY + r > by && prevY - r < by + bh) {
    tey = -Infinity;
    teyt = Infinity;
  } else {
    return null;
  }

  // The swept box crosses the brick iff the two overlap intervals intersect
  // somewhere inside this step.
  const tIn = Math.max(tex, tey);
  const tOut = Math.min(text, teyt);
  if (tIn > tOut || tOut < 0 || tIn > 1) return null;

  // The face that was hit is the axis with the SMALLER penetration (the rule
  // from ISSUES.md #1). Read it from the position where the ball actually
  // stands against the brick: the previous one when it was already overlapping
  // (the grid seams overlap two bricks in the same pass), the current one when
  // the ball just arrived this step.
  if (overlapsBox(prevX, prevY, ball.r, brick)) {
    return faceByPenetration(prevX, prevY, ball.r, brick);
  }
  if (overlapsBox(ball.x, ball.y, ball.r, brick)) {
    return faceByPenetration(ball.x, ball.y, ball.r, brick);
  }

  // Neither position overlaps the brick: the ball crossed it without ever
  // stopping inside (tunnelling). The sweep is all we have — the axis that
  // entered LAST is the face that was hit; equal entry times mean a corner.
  if (
    Number.isFinite(tex) &&
    Number.isFinite(tey) &&
    Math.abs(tex - tey) <= PEN_EPS
  ) {
    return 'corner';
  }
  if (tex > tey) return ball.vx > 0 ? 'left' : 'right';
  if (tey > tex) return ball.vy > 0 ? 'top' : 'bottom';

  // Defensive fallback: no direction information anywhere, use the smallest
  // penetration at the current position.
  return faceByPenetration(ball.x, ball.y, ball.r, brick);
}

// True if the circle (cx, cy, r) overlaps the brick rectangle.
function overlapsBox(cx, cy, r, brick) {
  return (
    cx + r > brick.x &&
    cx - r < brick.x + brick.w &&
    cy + r > brick.y &&
    cy - r < brick.y + brick.h
  );
}

// The face of the brick hit by a ball centred at (cx, cy): the axis with the
// smaller penetration is the face that was hit, and two equal penetrations
// (within PEN_EPS) mean a diagonal corner hit.
function faceByPenetration(cx, cy, r, brick) {
  const pens = [
    { face: 'left', v: cx + r - brick.x },
    { face: 'right', v: brick.x + brick.w - (cx - r) },
    { face: 'top', v: cy + r - brick.y },
    { face: 'bottom', v: brick.y + brick.h - (cy - r) },
  ];
  pens.sort((a, b) => a.v - b.v);
  if (pens[1].v - pens[0].v <= PEN_EPS) return 'corner';
  return pens[0].face;
}

// Applies the bounce for a face hit: flips the velocity component of the hit
// axis and pushes the ball back outside the brick rectangle, otherwise it
// still overlaps on the next frame and re-flips forever (sticky bounce). The
// flips use the absolute value so they are idempotent: the grid gap is 8 px
// and the ball 14 px across, so every seam overlaps two bricks in the same
// pass and `vy = -vy` applied twice would cancel out and let the ball through.
function resolveBrickBounce(ball, brick, face) {
  switch (face) {
    case 'left':
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
      break;
    case 'right':
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
      break;
    case 'top':
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
      break;
    case 'bottom':
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
      break;
    default: {
      // corner: flip both components and push the ball out diagonally
      const cameFromLeft = ball.vx > 0;
      const cameFromTop = ball.vy > 0;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      ball.x = cameFromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
      ball.y = cameFromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
  }
}


